changeSet.sql:
ALTER TABLE plots DROP CONSTRAINT chk_plots_status;
ALTER TABLE plots ADD CONSTRAINT chk_plots_status
    CHECK (status IN ('AVAILABLE_DEV', 'AVAILABLE_INV', 'RESERVED', 'SOLD', 'WITHHELD', 'ON_PLAN'));

changeSet.rollback:
ALTER TABLE plots DROP CONSTRAINT chk_plots_status;
ALTER TABLE plots ADD CONSTRAINT chk_plots_status
    CHECK (status IN ('AVAILABLE_DEV', 'AVAILABLE_INV', 'RESERVED', 'SOLD', 'WITHHELD'));

changeSet.sql:
ALTER TABLE payments
    ADD COLUMN purpose varchar(16) NOT NULL DEFAULT 'OUTRIGHT',
    ADD CONSTRAINT chk_payments_purpose CHECK (purpose IN ('OUTRIGHT', 'DEPOSIT'));
COMMENT ON COLUMN payments.purpose IS
    'What the payment was for: the full price (OUTRIGHT) or an instalment plan''s DEPOSIT. Instalments come with phase 3b.';

CREATE SEQUENCE provisional_letter_number_seq;
GRANT USAGE ON SEQUENCE provisional_letter_number_seq TO ${appDbUsername};

ALTER TABLE allocation_letters
    ADD COLUMN kind varchar(16) NOT NULL DEFAULT 'ALLOCATION',
    ADD CONSTRAINT chk_allocation_letters_kind CHECK (kind IN ('ALLOCATION', 'PROVISIONAL')),
    DROP CONSTRAINT uq_allocation_letters_transaction,
    ADD CONSTRAINT uq_allocation_letters_transaction_kind UNIQUE (transaction_id, kind);
COMMENT ON COLUMN allocation_letters.kind IS
    'PROVISIONAL: issued when an instalment plan''s deposit is verified (HT-PAL-…); ALLOCATION: the final letter (HT-ALC-…).';

changeSet.rollback:
ALTER TABLE allocation_letters
    DROP CONSTRAINT uq_allocation_letters_transaction_kind,
    ADD CONSTRAINT uq_allocation_letters_transaction UNIQUE (transaction_id),
    DROP CONSTRAINT chk_allocation_letters_kind,
    DROP COLUMN kind;
DROP SEQUENCE provisional_letter_number_seq;
